"""Схема базы и миграции. Одна схема на SQLite и PostgreSQL: различаются только типы id и дробных чисел."""
from __future__ import annotations

from typing import List, Tuple

from store.db import Database

TYPES = {
    "sqlite": {"ID": "INTEGER PRIMARY KEY AUTOINCREMENT", "FLOAT": "REAL"},
    "postgresql": {"ID": "BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY", "FLOAT": "DOUBLE PRECISION"},
}

# (версия, операторы). Новые изменения — только новой версией в конце списка.
MIGRATIONS: List[Tuple[int, List[str]]] = [
    (1, [
        """CREATE TABLE users (
            id {ID}, login TEXT NOT NULL UNIQUE, name TEXT NOT NULL, role TEXT NOT NULL,
            password_hash TEXT NOT NULL, must_change INTEGER NOT NULL DEFAULT 0,
            blocked INTEGER NOT NULL DEFAULT 0, failed_logins INTEGER NOT NULL DEFAULT 0,
            locked_until {FLOAT}, created_at {FLOAT} NOT NULL, last_login {FLOAT})""",
        """CREATE TABLE sessions (
            token_hash TEXT PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id),
            created_at {FLOAT} NOT NULL, expires_at {FLOAT} NOT NULL, last_seen {FLOAT} NOT NULL, ip TEXT)""",
        """CREATE TABLE audit (
            id {ID}, at {FLOAT} NOT NULL, user_id BIGINT, login TEXT, action TEXT NOT NULL,
            object TEXT, details TEXT, ip TEXT, prev_hash TEXT NOT NULL, hash TEXT NOT NULL)""",
        "CREATE INDEX audit_at ON audit (at)",
        """CREATE TABLE study_groups (
            id {ID}, name TEXT NOT NULL, teacher_id BIGINT NOT NULL REFERENCES users(id), created_at {FLOAT} NOT NULL)""",
        """CREATE TABLE group_members (
            group_id BIGINT NOT NULL REFERENCES study_groups(id), user_id BIGINT NOT NULL REFERENCES users(id),
            PRIMARY KEY (group_id, user_id))""",
        """CREATE TABLE scenarios (
            id {ID}, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, mode TEXT NOT NULL, role TEXT,
            difficulty INTEGER NOT NULL DEFAULT 1, categories TEXT, status TEXT NOT NULL, source TEXT NOT NULL,
            body TEXT NOT NULL, author_id BIGINT, created_at {FLOAT} NOT NULL, updated_at {FLOAT} NOT NULL)""",
        """CREATE TABLE assignments (
            id {ID}, scenario_id BIGINT NOT NULL REFERENCES scenarios(id), group_id BIGINT NOT NULL REFERENCES study_groups(id),
            teacher_id BIGINT NOT NULL REFERENCES users(id), note TEXT, created_at {FLOAT} NOT NULL)""",
        """CREATE TABLE lessons (
            id {ID}, teacher_id BIGINT NOT NULL REFERENCES users(id), mode TEXT NOT NULL, scenario TEXT, title TEXT,
            group_id BIGINT, config TEXT, state TEXT NOT NULL, created_at {FLOAT} NOT NULL,
            started_at {FLOAT}, finished_at {FLOAT})""",
        """CREATE TABLE lesson_events (
            id {ID}, lesson_id BIGINT NOT NULL REFERENCES lessons(id), at {FLOAT} NOT NULL, kind TEXT NOT NULL,
            user_id BIGINT, data TEXT)""",
        "CREATE INDEX lesson_events_lesson ON lesson_events (lesson_id)",
        """CREATE TABLE results (
            id {ID}, lesson_id BIGINT NOT NULL REFERENCES lessons(id), user_id BIGINT NOT NULL REFERENCES users(id),
            role TEXT, score INTEGER NOT NULL, findings TEXT NOT NULL, summary TEXT, created_at {FLOAT} NOT NULL,
            expert_score INTEGER, expert_comment TEXT, expert_by BIGINT, expert_at {FLOAT})""",
        "CREATE INDEX results_user ON results (user_id)",
        "CREATE INDEX results_lesson ON results (lesson_id)",
        """CREATE TABLE student_cards (
            id {ID}, lesson_id BIGINT NOT NULL REFERENCES lessons(id), user_id BIGINT NOT NULL REFERENCES users(id),
            code TEXT, card TEXT NOT NULL, created_at {FLOAT} NOT NULL)""",
        """CREATE TABLE materials (
            id {ID}, title TEXT NOT NULL, filename TEXT NOT NULL, path TEXT NOT NULL, size BIGINT NOT NULL,
            uploaded_by BIGINT NOT NULL REFERENCES users(id), created_at {FLOAT} NOT NULL)""",
        "CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL)",
    ]),
    (2, [
        # Задания (узел 6): группе назначается пакет сценариев с параметрами; обучающийся выполняет его сам.
        # Таблица assignments из версии 1 ссылалась только на сценарии из базы — заменена.
        "DROP TABLE assignments",
        """CREATE TABLE tasks (
            id {ID}, teacher_id BIGINT NOT NULL REFERENCES users(id), group_id BIGINT NOT NULL REFERENCES study_groups(id),
            pack_id TEXT NOT NULL, title TEXT NOT NULL, difficulty INTEGER, config TEXT NOT NULL, note TEXT,
            due_at {FLOAT}, archived INTEGER NOT NULL DEFAULT 0, created_at {FLOAT} NOT NULL)""",
        "CREATE INDEX tasks_group ON tasks (group_id)",
        "ALTER TABLE study_groups ADD COLUMN archived INTEGER NOT NULL DEFAULT 0",
        "ALTER TABLE materials ADD COLUMN description TEXT",
        "ALTER TABLE materials ADD COLUMN content_type TEXT",
        "ALTER TABLE materials ADD COLUMN group_id BIGINT",
        """CREATE TABLE feedback (
            id {ID}, teacher_id BIGINT NOT NULL REFERENCES users(id), student_id BIGINT NOT NULL REFERENCES users(id),
            text TEXT NOT NULL, created_at {FLOAT} NOT NULL)""",
        "CREATE INDEX feedback_student ON feedback (student_id)",
    ]),
]


def current_version(db: Database) -> int:
    db.execute("CREATE TABLE IF NOT EXISTS schema_version (version INTEGER NOT NULL)")
    return db.scalar("SELECT MAX(version) AS v FROM schema_version") or 0


def migrate(db: Database) -> int:
    """Доводит схему до последней версии. Идемпотентно. Возвращает итоговую версию."""
    types = TYPES[db.dialect]
    version = current_version(db)
    for number, statements in MIGRATIONS:
        if number <= version:
            continue
        with db.transaction():
            for sql in statements:
                db.execute(sql.format(**types))
            db.execute("INSERT INTO schema_version (version) VALUES (?)", (number,))
        version = number
    return version
